"""Film units: פיזיקה סביבנו (existing course 'physics', grades 6-8) and מסע אל הקרינה (existing course 'radiation', grades 7-8).

Observable, measurable physics only: forces, gravity, energy, pressure, electricity, magnetism, waves and the
electromagnetic spectrum, with the people who discovered them and safe "try at home" observations. No origin
stories of the universe and no "billions of years". Wonder at the Creator's world appears only where it is natural
(the beracha on lightning and thunder, the rainbow, the Rambam on contemplating creation, the first light).
"""
from know_films import S, Q, L, U, course


def sv(l2, more=None):
    """Narration for the physics course: level 2, and what level 3 adds after the level-2 lines."""
    d = {2: l2}
    if more:
        d[3] = l2 + more
    return d


